import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,t,p})=>{let tau=t%10,s=p[0]*tau,x=-1.3+2.6*s/100;g.line([-1.4,.4,0],[1.4,.4,0]);g.box(x,.15,0,.16,.14,.15,C.gold);let pts=Array.from({length:41},(_,i)=>[tau*i/40,p[0]*tau*i/40]);g.plot({title:b('Distance (m) vs time (s)','दूरी (m) बनाम समय (s)'),xMax:10,yMax:100,xLabel:'s',points:pts,marker:[tau,s]});return[read('Time','समय',fmt(tau),'s'),read('Distance','दूरी',fmt(s),'m'),read('Slope = speed','ढाल = चाल',p[0],'m/s')];};
